+         eh->e_ident[EI_MAG1] == ELFMAG1 &&
+         eh->e_ident[EI_MAG2] == ELFMAG2 &&
+         eh->e_ident[EI_MAG3] == ELFMAG3)) {
+        munmap(file, st.st_size);
+        return false;
+    }
